import { ImageResponse } from "next/og";

// Edge runtime can't read the content file per request (no fs), so this card's
// brand text is imported from the JSON at BUILD time — the one documented
// exception to the per-request rule. It refreshes on the next deploy, which is
// exactly when social scrapers re-fetch the card. See content/SCHEMA.md.
import siteContent from "@/content/site-content.json";

const siteName = siteContent.site.name;
const siteTagline = siteContent.site.tagline;

// Edge runtime is required here: @vercel/og's Node build fails to resolve
// its bundled assets when the project path contains spaces (Windows dev).
export const runtime = "edge";

export const alt = `${siteName} — ${siteTagline}`;

export const size = {
  width: 1200,
  height: 630,
};

export const contentType = "image/png";

const CREAM = "#F1ECEC";
const LAVENDER = "#A092BE";
const LAVENDER_LIGHT = "#CFC8E2";

// The stones/cairn photo (public/home-hero.jpg) embedded as a data URI so the
// social share card is fully self-contained on the Edge runtime.
const STONES =
  "data:image/jpeg;base64,";

export default async function OpenGraphImage() {
  // Site fonts (Playfair Display for the wordmark, Inter for the tagline),
  // loaded from co-located files so the card matches the website typography.
  const [playfair, inter] = await Promise.all([
    fetch(new URL("./playfair-700.ttf", import.meta.url)).then((r) => r.arrayBuffer()),
    fetch(new URL("./inter-500.ttf", import.meta.url)).then((r) => r.arrayBuffer()),
  ]);

  return new ImageResponse(
    (
      <div
        style={{
          position: "relative",
          overflow: "hidden",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img
          src={STONES}
          width={1200}
          height={800}
          style={{
            position: "absolute",
            top: -85,
            left: 0,
            width: 1200,
            height: 800,
          }}
        />

        {/* Light overall wash — keeps the warm photo bright while unifying it
            with the brand teal. */}
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            display: "flex",
            backgroundColor: "rgba(34,57,74,0.22)",
          }}
        />
        {/* Soft dark band across the vertical middle so the centered wordmark
            stays legible, while the top and bottom of the photo stay bright. */}
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            display: "flex",
            backgroundImage:
              "linear-gradient(180deg, rgba(18,33,43,0) 22%, rgba(18,33,43,0.5) 43%, rgba(18,33,43,0.5) 63%, rgba(18,33,43,0) 84%)",
          }}
        />

        {/* Wordmark centered on both axes and kept inside the middle ~600px so
            platforms that crop the 1200x630 card to a centered square (e.g.
            Facebook comment thumbnails) still show the full name. */}
        <div
          style={{
            position: "relative",
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            textAlign: "center",
            padding: "0 120px",
          }}
        >
          <div
            style={{
              display: "flex",
              width: 96,
              height: 4,
              backgroundColor: LAVENDER,
              borderRadius: 2,
              marginBottom: 28,
            }}
          />
          <div
            style={{
              display: "flex",
              fontFamily: "Playfair Display",
              fontSize: 58,
              fontWeight: 700,
              color: CREAM,
              letterSpacing: "-0.01em",
            }}
          >
            {siteName}
          </div>
          <div
            style={{
              display: "flex",
              fontFamily: "Inter",
              fontSize: 32,
              fontWeight: 500,
              color: LAVENDER_LIGHT,
              letterSpacing: "0.08em",
              marginTop: 20,
            }}
          >
            {siteTagline}
          </div>
        </div>
      </div>
    ),
    {
      ...size,
      fonts: [
        { name: "Playfair Display", data: playfair, weight: 700, style: "normal" },
        { name: "Inter", data: inter, weight: 500, style: "normal" },
      ],
    }
  );
}
